<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus, Search, X } from 'lucide-vue-next'
import { adminApi, rows } from '@/api/services'
import { apiMessage } from '@/api/client'
import { money } from '@/utils'
import type { Platform, Product, Sku } from '@/types'
import AdminPageHeader from '@/components/AdminPageHeader.vue'
import UiStatus from '@/components/UiStatus.vue'
const route=useRoute();const kind=computed(()=>route.path.split('/').pop() as 'platforms'|'products'|'skus');const labels={platforms:'平台',products:'商品',skus:'SKU'};const items=ref<any[]>([]),platforms=ref<Platform[]>([]),products=ref<Product[]>([]),query=ref(''),dialog=ref(false),editing=ref<any>(),error=ref('');const form=ref<any>({})
async function load(){error.value='';try{items.value=rows(await adminApi.list(kind.value,{q:query.value}));platforms.value=rows(await adminApi.platforms());products.value=rows(await adminApi.products())}catch(e){error.value=apiMessage(e)}}
function open(item?:any){editing.value=item;form.value=item?{...item}:{enabled:true,sort:0};dialog.value=true}
async function save(){try{editing.value?await adminApi.update(kind.value,editing.value.id,form.value):await adminApi.create(kind.value,form.value);dialog.value=false;load()}catch(e){error.value=apiMessage(e)}}
watch(kind,load);onMounted(load)
</script>
<template><AdminPageHeader :title="labels[kind]+'管理'" :description="kind==='platforms'?'维护商品所属的代理平台':kind==='products'?'维护商品信息、热门推荐及上下架状态':'维护销售规格、价格与状态'"><button class="btn btn--primary btn--sm" @click="open()"><Plus/>新增{{labels[kind]}}</button></AdminPageHeader><div class="admin-toolbar"><label class="search-field"><Search/><input v-model="query" :placeholder="`搜索${labels[kind]}`" @keyup.enter="load"/></label><button class="btn btn--secondary btn--sm" @click="load">查询</button></div><div v-if="error" class="alert alert--error">{{error}}</div><div class="data-panel"><div class="table-wrap"><table><thead><tr><th>名称</th><th v-if="kind==='platforms'">标识 / 官网</th><th v-if="kind==='products'">平台 / 标识</th><th v-if="kind==='products'">推荐</th><th v-if="kind==='skus'">商品</th><th v-if="kind==='skus'">售价 / 库存</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.name}}</strong><small>ID {{item.id}}</small></td><td v-if="kind==='platforms'">{{item.slug}}<small>{{item.website||'-'}}</small></td><td v-if="kind==='products'">{{item.platform?.name||item.platform_id}}<small>{{item.slug}}</small></td><td v-if="kind==='products'">{{Number(item.sort)>0?`热门 #${item.sort}`:'普通商品'}}</td><td v-if="kind==='skus'">{{item.product?.name||item.product_id}}</td><td v-if="kind==='skus'">{{money(item.price)}}<small>库存 {{item.stock??'-'}}</small></td><td><UiStatus :value="item.enabled===false?'disabled':'enabled'"/></td><td class="actions"><button class="btn btn--ghost btn--sm" @click="open(item)">编辑</button></td></tr></tbody></table></div><div v-if="!items.length" class="state">暂无{{labels[kind]}}</div></div><div v-if="dialog" class="modal-backdrop" @click.self="dialog=false"><div class="modal"><div class="modal-head"><h2>{{editing?'编辑':'新增'}}{{labels[kind]}}</h2><button class="icon-btn" @click="dialog=false"><X/></button></div><form @submit.prevent="save"><label v-if="kind==='products'" class="form-field"><span>所属平台</span><select v-model.number="form.platform_id" required><option disabled value="">请选择</option><option v-for="p in platforms" :value="p.id" :key="p.id">{{p.name}}</option></select></label><label v-if="kind==='skus'" class="form-field"><span>所属商品</span><select v-model.number="form.product_id" required><option disabled value="">请选择</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.name}}</option></select></label><label class="form-field"><span>名称</span><input v-model="form.name" required/></label><label v-if="kind!=='skus'" class="form-field"><span>URL 标识</span><input v-model="form.slug" required/></label><label v-if="kind==='platforms'" class="form-field"><span>官网</span><input v-model="form.website" type="url"/></label><label v-if="kind==='products'" class="form-field"><span>商品描述</span><textarea v-model="form.description"/></label><label v-if="kind==='products'" class="form-field"><span>推荐排序</span><input v-model.number="form.sort" type="number" min="0" step="1"/><small>0 为普通商品；大于 0 时进入热门推荐，数值越大越靠前</small></label><label v-if="kind==='skus'" class="form-field"><span>销售价格</span><input v-model.number="form.price" type="number" min="0.01" step="0.01" required/></label><label class="check-row"><input v-model="form.enabled" type="checkbox"/><span>启用</span></label><button class="btn btn--primary btn--wide">保存</button></form></div></div></template>
